# Knapsack rolling array: keep 2 rows
def knapsack_2row(wt, val, W):
    prev = [0] * (W + 1)
    for w, v in zip(wt, val):
        cur = prev[:]
        for c in range(w, W + 1):
            cur[c] = max(cur[c], prev[c - w] + v)
        prev = cur
    return prev[W]

# Vertex cover 2-approximation:
def approx_vc(n, edges):
    cover, used = set(), set()
    for u, v in edges:
        if u not in used and v not in used:
            cover.add(u); cover.add(v)
            used.add(u); used.add(v)
    return cover  # |cover| <= 2 * OPT
